# -*- coding: utf-8 -*-
"""Числовые значения интерфейса и встроенная справка; не требует Qt."""
import math
from html import escape


# ========================================================================
# Числа без потери точности
# ========================================================================

def compact(value,digits=6):
    value=float(value)
    if not math.isfinite(value):raise ValueError("Число должно быть конечным")
    return format(0. if value==0 else value,f".{digits}g")


def length_text(value):
    a=abs(value)
    factor,unit=(1.,"м") if a>=1 else ((1e-3,"мм") if a>=1e-3 else (1e-6,"мкм"))
    return compact(value/factor,5)+" "+unit


class NumberValue:
    """Физическое значение хранится отдельно от округлённого текста."""
    def __init__(self,value,factor=1.,minimum=0.,maximum=1e12):
        self.factor=factor
        self.minimum=minimum
        self.maximum=maximum
        self.set_value(value)

    def set_value(self,value):
        value=float(value)
        if not math.isfinite(value) or not self.minimum<=value<=self.maximum:
            raise ValueError(f"Допустим диапазон {self.minimum:g} … {self.maximum:g}")
        self.raw=value
        return self.display()

    def display(self):
        self.last_text=compact(self.raw/self.factor,12)
        return self.last_text

    def commit(self,text):
        text=text.strip()
        if text==self.last_text:return self.raw
        try:value=float(text.replace(",","."))*self.factor
        except ValueError:raise ValueError("Введите число: например 5,7 или 5.7e-6") from None
        self.set_value(value)
        return self.raw

    def change_factor(self,factor):
        if not math.isfinite(factor) or factor<=0:raise ValueError("Некорректная единица")
        self.factor=factor
        return self.display()


