def number(x,digits=6):return format(x,f".{digits}g").replace(".",",")
def result_table(law,mode):
    e=EXAMPLES[(law,mode)]
    if law=="uniform":
        return f"<table width='100%'><tr><th>Результат</th><th>Значение</th></tr><tr><td>Ячеек от стенки</td><td>{e['n']}</td></tr><tr><td>Минимальный шаг по линиям</td><td>{number(e['step_min_um'],7)} мкм</td></tr><tr><td>Максимальный шаг по линиям</td><td>{number(e['hmax_um'],7)} мкм</td></tr></table>"

    parameter="q" if law=="geometric" else ("p" if law=="power" else "β")
    return f"<table width='100%'><tr><th>Результат</th><th>Значение</th></tr><tr><td>Ячеек от стенки</td><td>{e['n']}</td></tr><tr><td>Подобранный {parameter} по линиям</td><td>{number(e['parameter_min'],8)} … {number(e['parameter_max'],8)}</td></tr><tr><td>Максимальный размер от стенки</td><td>{number(e['hmax_um'],7)} мкм</td></tr><tr><td>Максимальный фактический рост соседних ячеек</td><td>{number(e['growth_percent'],5)} %</td></tr></table>"
